     "py": "def links(topology, n):\n    return {\"ستاره\": n - 1, \"حلقه\": n, \"باس\": 1, \"مش کامل\": n * (n - 1) // 2}[topology]\nprint(f\"{'n':>4} | ستاره | حلقه | مش کامل\")\nfor n in (4, 10, 50, 100): print(f\"{n:4} | {links('ستاره', n):5} | {links('حلقه', n):4} | {links('مش کامل', n):7}\")\n# مقاومت در برابر خرابی: خرابی یک پیوند چند جفت دستگاه را از هم جدا می‌کند؟\nimport itertools\ndef connected(nodes, edges):\n    seen, stack = {nodes[0]}, [nodes[0]]\n    while stack:\n        u = stack.pop()\n        for a, b in edges:\n            for x, y in ((a, b), (b, a)):\n                if x == u and y not in seen: seen.add(y); stack.append(y)\n    return len(seen) == len(nodes)\nnodes = list(range(6)); star = [(0, i) for i in range(1, 6)]; ring = [(i, (i + 1) % 6) for i in range(6)]\nfor name, E in [(\"ستاره\", star), (\"حلقه\", ring)]:\n    survive = sum(connected(nodes, [e for e in E if e != cut]) for cut in E); print(name, f\"با قطع هر یک پیوند: {survive}/{len(E)} حالت متصل می‌ماند\")"
