     "py": "def best_medium(distance_m, speed_gbps, emi_high=False):\n    options = []\n    if distance_m <= 100 and speed_gbps <= 10 and not emi_high: options.append(\"UTP Cat6/6a\")\n    if distance_m <= 400 and speed_gbps <= 100: options.append(\"فیبر چندحالته OM4\")\n    if distance_m <= 80000: options.append(\"فیبر تک‌حالته\")\n    return options\nfor d, s, e in [(50, 1, False), (800, 10, False), (60, 1, True), (5000, 100, False)]: print(f\"{d:5} m، {s:3} Gbps، EMI={e}: {best_medium(d, s, e)}\")\nimport math\nloss_db = lambda km, alpha: km * alpha; print(\"تضعیف ۲۰ کیلومتر فیبر تک‌حالته (۰٫۲dB/km):\", loss_db(20, .2), \"dB | نسبت توان:\", round(10 ** (-loss_db(20, .2) / 10), 3))"
