     "py": "WELL = {20: \"FTP-data\", 21: \"FTP\", 22: \"SSH\", 23: \"Telnet\", 25: \"SMTP\", 53: \"DNS\", 67: \"DHCP\", 80: \"HTTP\", 110: \"POP3\", 123: \"NTP\", 143: \"IMAP\", 161: \"SNMP\", 443: \"HTTPS\", 3306: \"MySQL\", 3389: \"RDP\", 5432: \"PostgreSQL\"}\ndef rng(p): return \"well-known\" if p < 1024 else \"registered\" if p < 49152 else \"ephemeral\"\nfor p in (22, 443, 8080, 50000): print(p, WELL.get(p, \"—\"), rng(p))\nimport socket\ns = socket.socket(); s.bind((\"127.0.0.1\", 0)); s.listen(); port = s.getsockname()[1]\nc = socket.create_connection((\"127.0.0.1\", port)); print(\"سرور روی پورت\", port, \"| کلاینت از پورت موقت\", c.getsockname()[1])\nprint(\"چهارتایی اتصال:\", c.getsockname(), \"→\", c.getpeername()); c.close(); s.close()"
