     "py": "PERM = {\"R\": 1, \"W\": 2, \"M\": 4}\ndef effective(share_perm, ntfs_perm): return min(PERM[share_perm], PERM[ntfs_perm])\ninv = {1: \"خواندن\", 2: \"نوشتن\", 4: \"مدیریت\"}\nprint(\"share=M ntfs=R →\", inv[effective(\"M\", \"R\")]); print(\"share=W ntfs=M →\", inv[effective(\"W\", \"M\")])\nacl = {\"/finance\": {\"acc\": \"W\", \"staff\": None}, \"/shared\": {\"acc\": \"W\", \"staff\": \"W\"}, \"/hr\": {\"hr\": \"M\"}}\ndef can(user_groups, path, need):\n    perms = acl.get(path, {}); best = max([PERM[p] for g, p in perms.items() if g in user_groups and p] or [0]); return best >= PERM[need]\nprint(\"staff می‌تواند /finance بخواند؟\", can([\"staff\"], \"/finance\", \"R\")); print(\"acc می‌تواند /finance بنویسد؟\", can([\"acc\"], \"/finance\", \"W\")); print(\"hr مدیریت /hr؟\", can([\"hr\"], \"/hr\", \"M\"))"
