     "py": "routes = [{\"via\": \"ISP-A\", \"lp\": 100, \"aspath\": [64501, 64510], \"med\": 0}, {\"via\": \"ISP-B\", \"lp\": 200, \"aspath\": [64502, 64503, 64510], \"med\": 0}, {\"via\": \"ISP-C\", \"lp\": 100, \"aspath\": [64504, 64510], \"med\": 50}]\ndef bgp_best(rs):\n    return sorted(rs, key=lambda r: (-r[\"lp\"], len(r[\"aspath\"]), r[\"med\"]))[0]\nprint(\"برنده:\", bgp_best(routes)[\"via\"], \"(LocalPref بزرگ‌تر از AS-PATH مهم‌تر است)\")\nroutes[1][\"lp\"] = 100; print(\"با LP برابر:\", bgp_best(routes)[\"via\"])\ndef prepend(r, asn, n): r = dict(r); r[\"aspath\"] = [asn] * n + r[\"aspath\"]; return r\nprint(\"AS-PATH prepending برای نامطلوب‌کردن مسیر:\", prepend(routes[0], 65000, 3)[\"aspath\"])"
