     "py": "import heapq\ndef stp(switches, links):\n    root = min(switches, key=lambda s: (switches[s], s)); adj = {s: [] for s in switches}\n    for a, b, c in links: adj[a].append((b, c)); adj[b].append((a, c))\n    dist = {root: 0}; pq = [(0, root)]; parent = {}\n    while pq:\n        d, u = heapq.heappop(pq)\n        if d > dist.get(u, 1e9): continue\n        for v, c in adj[u]:\n            if d + c < dist.get(v, 1e9): dist[v] = d + c; parent[v] = u; heapq.heappush(pq, (d + c, v))\n    fwd = {frozenset((v, p)) for v, p in parent.items()}\n    blocked = [(a, b) for a, b, c in links if frozenset((a, b)) not in fwd]\n    return root, dist, blocked\nsw = {\"A\": 32768, \"B\": 32768, \"C\": 4096, \"D\": 32768}; lk = [(\"A\", \"B\", 4), (\"B\", \"C\", 4), (\"C\", \"A\", 4), (\"C\", \"D\", 19), (\"A\", \"D\", 19)]\nroot, dist, blocked = stp(sw, lk); print(\"ریشه:\", root, \"| هزینه تا ریشه:\", dist, \"| پیوندهای مسدود:\", blocked)"
