     "py": "import ssl, hashlib, datetime\nchain = [(\"example.com\", \"R3 Intermediate\"), (\"R3 Intermediate\", \"ISRG Root X1\"), (\"ISRG Root X1\", \"ISRG Root X1\")]\ntrust = {\"ISRG Root X1\"}\ndef verify(chain, host, today):\n    leaf = chain[0]\n    if host != leaf[0]: return \"نام میزبان نمی‌خواند\"\n    for (subj, issuer), nxt in zip(chain, chain[1:] + [None]):\n        if nxt and nxt[0] != issuer: return \"زنجیره گسسته\"\n    return \"معتبر\" if chain[-1][1] in trust else \"ریشه‌ی نامعتبر\"\nprint(verify(chain, \"example.com\", None), \"|\", verify(chain, \"evil.com\", None), \"|\", verify(chain[:1], \"example.com\", None))\nprint(\"نسخه‌ها:\", [v.name for v in ssl.TLSVersion][:5]); print(\"خطاها: منقضی، نام نامطابق، ریشه ناشناخته، ابطال، ساعت اشتباه\")"
