     "py": "class Firewall:\n    def __init__(self, rules): self.rules, self.state = rules, set()\n    def pkt(self, src, dst, proto, dport, sport=40000):\n        if (dst, src, proto, sport) in self.state: return \"allow (stateful return)\"\n        for s, d, p, port, act in self.rules:\n            if s in (src, \"*\") and d in (dst, \"*\") and p in (proto, \"*\") and port in (dport, \"*\"):\n                if act == \"allow\": self.state.add((src, dst, proto, dport))\n                return act\n        return \"deny (default)\"\nfw = Firewall([(\"inside\", \"outside\", \"tcp\", 443, \"allow\"), (\"outside\", \"dmz\", \"tcp\", 443, \"allow\"), (\"dmz\", \"inside\", \"*\", \"*\", \"deny\")])\nprint(fw.pkt(\"inside\", \"outside\", \"tcp\", 443)); print(fw.pkt(\"outside\", \"inside\", \"tcp\", 22)); print(fw.pkt(\"outside\", \"dmz\", \"tcp\", 443)); print(fw.pkt(\"dmz\", \"inside\", \"tcp\", 445))"
